<template>
  <MarketplaceLayout><main class="market-container green-community">
    <header class="community-hero"><div><span class="community-eyebrow"><MarketIcon name="sprout"/>GÓC XANH BONSAIMARKET</span><h1>Cộng đồng BonsaiMarket</h1><p>Mỗi góc vườn, một câu chuyện. Cùng hỏi đáp, chia sẻ kinh nghiệm và tìm lời khuyên cho cây của bạn.</p></div><RouterLink class="button button-primary" :to="isAuthenticated?'/community/create':{path:'/login',query:{redirect:'/community/create'}}">{{ isAuthenticated?'Chia sẻ bài viết':'Đăng nhập để chia sẻ' }}</RouterLink></header>
    <div class="community-layout"><nav class="community-navigation" aria-label="Nội dung cộng đồng"><RouterLink :to="filter('')" :aria-current="!route.query.type&&!route.query.scope?'page':undefined"><MarketIcon name="users"/>Tất cả bài viết</RouterLink><RouterLink v-for="(label,key) in postTypes" :key="key" :to="filter(key)" :aria-current="route.query.type===key?'page':undefined"><MarketIcon :name="key==='PLANT_HELP'?'sprout':key==='QUESTION'?'chat':'leaf'"/>{{ label }}</RouterLink><RouterLink v-if="isAuthenticated" :to="{path:'/community',query:{scope:'MINE'}}" :aria-current="route.query.scope==='MINE'?'page':undefined"><MarketIcon name="user"/>Bài viết của tôi</RouterLink><RouterLink v-if="isAuthenticated" :to="{path:'/community',query:{scope:'SAVED'}}" :aria-current="route.query.scope==='SAVED'?'page':undefined"><MarketIcon name="bookmark"/>Bài đã lưu</RouterLink></nav>
      <section aria-label="Bảng tin cộng đồng"><form class="community-filter" @submit.prevent="search"><div><label for="community-search">Tìm kiếm bài viết</label><input id="community-search" v-model="keyword" type="search" maxlength="160" placeholder="Tên cây, triệu chứng, kinh nghiệm…"/></div><div><label for="community-topic">Chủ đề</label><select id="community-topic" v-model="topic"><option value="">Tất cả chủ đề</option><option v-for="(label,key) in topics" :key="key" :value="key">{{ label }}</option></select></div><button class="button button-outline">Tìm bài</button></form>
        <ResourceState v-if="loading||error" resource="bài viết" :loading="loading" :error="Boolean(error)" :error-message="error" @retry="load"/>
        <template v-else><p class="community-results" role="status">{{ data.totalElements }} bài viết{{ route.query.scope==='MINE'?' của bạn':route.query.scope==='SAVED'?' đã lưu':'' }}{{ route.query.type?' · '+postTypes[route.query.type]:'' }}</p><PostCard v-for="post in data.content" :key="post.id" :post="post"/><div v-if="!data.content.length" class="community-empty"><h2>Chưa có bài viết phù hợp</h2><p>Thử một từ khóa khác hoặc bắt đầu câu chuyện về góc xanh của bạn.</p><RouterLink to="/community">Xem tất cả bài viết</RouterLink></div><CatalogPagination :page="data.page" :total-pages="data.totalPages" label="Phân trang bài viết"/></template>
      </section>
      <aside class="community-aside"><section v-if="highlights.pinned.length" class="community-panel"><h2>Được ghim trong góc xanh</h2><ul><li v-for="post in highlights.pinned" :key="post.id"><RouterLink :to="'/community/posts/'+post.id">{{ post.title }}</RouterLink></li></ul></section><section v-if="highlights.topics.length" class="community-panel"><h2>Chủ đề trong cộng đồng</h2><ul><li v-for="item in highlights.topics" :key="item.topic"><RouterLink :to="{path:'/community',query:{topic:item.topic}}">{{ topics[item.topic] }} · {{ item.postCount }} bài công khai</RouterLink></li></ul></section><p v-if="highlightsError" role="alert">{{ highlightsError }} <button type="button" class="button button-outline" @click="loadHighlights">Thử lại</button></p><CommunityActivity v-if="isAuthenticated"/><section class="community-panel"><h2>Cùng giữ góc xanh tử tế</h2><ul><li>Chia sẻ trải nghiệm thật, trao đổi tôn trọng.</li><li>Lời khuyên chăm cây không thay thế việc quan sát cây thực tế.</li><li>Không spam, lộ thông tin riêng tư hoặc quảng cáo sai ngữ cảnh.</li></ul></section><section class="community-panel"><h2>Khám phá thêm</h2><p>Tìm hiểu cây từ người yêu cây và các gian hàng độc lập.</p><RouterLink to="/stores">Khám phá gian hàng</RouterLink><p><button type="button" class="text-link" @click="openChat">Mở trợ lý cây cảnh</button></p></section></aside>
    </div>
  </main></MarketplaceLayout>
</template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import MarketplaceLayout from '../../../layouts/MarketplaceLayout.vue';import ResourceState from '../../../components/marketplace/ResourceState.vue';import CatalogPagination from '../../../components/marketplace/CatalogPagination.vue';import MarketIcon from '../../../components/marketplace/MarketIcon.vue';import CommunityActivity from '../../../components/community/CommunityActivity.vue';import PostCard from '../../../components/community/PostCard.vue';import {marketplaceRequest as request} from '../../../services/marketplace.js';import {topics} from '../../../services/discussions.js';import {postTypes} from '../../../services/community.js';import {useAuth} from '../../../composables/useAuth.js';import '../../../css/community.css';
const route=useRoute(),router=useRouter(),{isAuthenticated}=useAuth(),keyword=ref(''),topic=ref(''),loading=ref(false),error=ref(''),data=ref({content:[],page:0,totalPages:0,totalElements:0});let generation=0;const highlights=ref({pinned:[],topics:[]}),highlightsError=ref('');
async function loadHighlights(){const ticket=generation;highlightsError.value='';try{const result=await request('/community/posts/highlights');if(ticket===generation)highlights.value=result;}catch(e){if(ticket===generation)highlightsError.value=e.message;}}

function filter(type){const query={...route.query};delete query.page;if(type)query.type=type;else delete query.type;return {path:'/community',query};}
function search(){const query={...route.query};delete query.page;for(const [key,value] of Object.entries({search:keyword.value.trim(),topic:topic.value})){if(value)query[key]=value;else delete query[key];}router.push({path:'/community',query});}
function openChat(event){window.dispatchEvent(new CustomEvent('agriverse-open-ai-expert',{detail:{opener:event.currentTarget}}));}
async function load(){const ticket=++generation;keyword.value=String(route.query.search||'');topic.value=String(route.query.topic||'');loading.value=true;error.value='';try{const params=new URLSearchParams();for(const key of ['search','topic','type','page','scope'])if(route.query[key])params.set(key,String(route.query[key]));if(route.query.scope&&!isAuthenticated.value){await router.replace({path:'/login',query:{redirect:route.fullPath}});return;}const result=await request((route.query.scope?'/account/community/posts?':'/community/posts?')+params);if(ticket===generation){if(result.totalPages>0&&result.page>=result.totalPages){await router.replace({path:route.path,query:{...route.query,page:String(result.totalPages-1)}});return;}data.value=result;await loadHighlights();}}catch(e){if(ticket===generation)error.value=e.message;}finally{if(ticket===generation)loading.value=false;}}
watch(()=>route.fullPath,load,{immediate:true});onBeforeUnmount(()=>generation++);
</script>
